<?php require 'config.php'; if(!empty($_SESSION['user_id'])){header('Location:index.php');exit;} $err=''; if($_SERVER['REQUEST_METHOD']==='POST'){check_token();try{$s=db()->prepare('SELECT * FROM users WHERE username=?');$s->execute([trim($_POST['username']??'')]);$u=$s->fetch();if($u&&password_verify((string)($_POST['password']??''),$u['password_hash'])){session_regenerate_id(true);$_SESSION['user_id']=$u['id'];$_SESSION['username']=$u['username'];header('Location:index.php');exit;}$err='Invalid username or password.';}catch(Throwable $e){$err='Database is not ready. Follow README.txt to import database.sql.';}} ?>
